import math
 
def sum_digits(n):
    sum = 0
    while n > 0:
        n, rem = divmod(n, 10)
        sum += rem
    return sum
 
def prime_factors(n):
    result = []
 
    for i in range(2, n + 1):
        while n % i == 0:
            result.append(i)
            n //= i
 
    return result
 
