def count_prime_factors(n):
    count = 0
    f = 2
    if n == 1:
        return 0
    if is_prime(n):
        return 1
    while True:
        if n % f == 0:
            count += 1
            n //= f
            if n == 1:
                return count
            if is_prime(n):
                f = n
        elif f >= 3:
            f += 2
        else:
            f = 3
 
