class FloatRange(start, endInclusive):
    def __init__(self, start, endInclusive):
        self.start = start
        self.endInclusive = endInclusive
 
def mapRange(range1, range2, value):
    if value not in range1:
        raise ValueError("value is not within the first range")
    if range1.endInclusive == range1.start:
        raise ValueError("first range cannot be single-valued")
    return range2.start + (value - range1.start) * (range2.endInclusive - range2.start) / (range1.endInclusive - range1.start)
 
