        text = f.read()
        words = re.findall(r'[A-Za-zÀ-ÿ]+', text.lower())
        word_count = {}
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1
        sorted_word_count = sorted(word_count.items(), key=operator.itemgetter(1))
