import random
import sys

base = 12
moves = [[1,-2],[2,-1],[2,1],[1,2],[-1,2],[-2,1],[-2,-1],[-1,-2]]
grid = []
total = 0

def main():
    global grid, total
    grid = [[0 for i in range(base)] for j in range(base)]
    total = (base - 4) * (base - 4)

    for r in range(base):
        for c in range(base):
            if r < 2 or r > base - 3 or c < 2 or c > base - 3:
                grid[r][c] = -1

    row = 2 + int(random.random() * (base - 4))
    col = 2 + int(random.random() * (base - 4))

    grid[row][col] = 1

    if solve(row, col, 2):
        printResult()
    else:
        print("no result")

def solve(r, c, count):
    global grid, total
    if count > total:
        return True

    nbrs = neighbors(r, c)

    if len(nbrs) == 0 and count!= total:
        return False

    nbrs.sort(key=lambda x: x[2])

    for nb in nbrs:
        r = nb[0]
        c = nb[1]
        grid[r][c] = count
        if not orphanDetected(count, r, c) and solve(r, c, count + 1):
            return True
        grid[r][c] = 0

    return False

def neighbors(r, c):
    nbrs = []

    for m in moves:
        x = m[0]
        y = m[1]
        if grid[r + y][c + x] == 0:
            num = countNeighbors(r + y, c + x)
            nbrs.append([r + y, c + x, num])

    return nbrs

def countNeighbors(r, c):
    num = 0
    for m in moves:
        if grid[r + m[1]][c + m[0]] == 0:
            num += 1
    return num

def orphanDetected(cnt, r, c):
    global total
    if cnt < total - 1:
        nbrs = neighbors(r, c)
        for nb in nbrs:
            if countNeighbors(nb[0], nb[1]) == 0:
                return True
    return False

def printResult():
    for row in grid:
        for i in row:
            if i == -1:
                continue
            sys.stdout.write("%2d " % i)
        print()

