def sieve(ss):
    c = [False] * ss
    c[1] = True
    for p in range(2, int(math.sqrt(ss))):
        if not c[p]:
            for i in range(p * p, ss, p):
                c[i] = True
    return c
 
def search(digits, pot, s, truncFunc):
    n = pot - 1
    pot //= 10
    while n >= pot:
        tn, tp = n, pot
        while tp > 0:
            if tn < tp or c[tn]:
                break
            tn = truncFunc(tn, tp)
            tp //= 10
        else:
            print("max", s, "truncatable:", n)
            return True
        n -= 2
    if digits > 1:
        return search(digits - 1, pot, s, truncFunc)
    return False
 
