class Xorshift_star:
    MASK64 = (1 << 64) - 1
    MASK32 = (1 << 32) - 1

    def __init__(self, seed = 0):
        self.state = seed & self.MASK64

    def next_int(self):
        x = self.state
        x =  x ^ (x >> 12) 
        x = (x ^ (x << 25)) & self.MASK64
        x =  x ^ (x >> 27) 
        self.state = x
        return (((x * 0x2545F4914F6CDD1D) & self.MASK64) >> 32) & self.MASK32

    def next_float(self):
        return self.next_int() / (1 << 32)

