import math
 
# Radix sort comparator for 32-bit two's complement integers
class radix_test:
    def __init__(self, offset):
        self.bit = offset
 
    def __call__(self, value):
        if self.bit == 31: # sign bit
            return value < 0 # negative int to left partition
        else:
            return not (value & (1 << self.bit)) # 0 bit to left partition
 
# Least significant digit radix sort
def lsd_radix_sort(first, last):
    for lsb in range(0, 32): # least-significant-bit
        first.stable_partition(radix_test(lsb))
 
# Most significant digit radix sort (recursive)
def msd_radix_sort(first, last, msb = 31):
    if first!= last and msb >= 0:
        mid = first.partition(radix_test(msb))
        msb -= 1 # decrement most-significant-bit
        msd_radix_sort(first, mid, msb) # sort left partition
        msd_radix_sort(mid, last, msb) # sort right partition
 
