double f(double x)
{
	return (x*x*x - 3*x*x + 2*x);
}
 
int main()
{
	double step = 0.001; // Smaller step values produce more accurate and precise results
	double start = -1;
	double stop = 3;
	double value = f(start);
	double sign = (value > 0);
 
	// Check for root at start
	if ( 0 == value )
		printf("Root found at %f\n", start);
 
	for(	double x = start + step;
			x <= stop;
			x += step )
	{
		value = f(x);
 
		if ( ( value > 0 )!= sign )
			// We passed a root
			printf("Root found near %f\n", x);
		else if ( 0 == value )
			// We hit a root
			printf("Root found at %f\n", x);
 
		// Update our sign
		sign = ( value > 0 );
