int circleSort(int a[], int lo, int hi, int swaps) {
    if (lo == hi) {
        return swaps;
    }
    int high = hi, low = lo;
    int mid = (hi - lo) / 2;
    while (lo < hi) {
        if (a[lo] > a[hi]) {
            int tmp = a[lo];
            a[lo] = a[hi];
            a[hi] = tmp;
            swaps++;
        }
        lo++;
        hi--;
    }
    if (lo == hi) {
        if (a[lo] > a[hi+1]) {
            int tmp = a[lo];
            a[lo] = a[hi+1];
            a[hi+1] = tmp;
            swaps++;
        }
    }
    swaps = circleSort(a, low, low+mid, swaps);
    swaps = circleSort(a, low+mid+1, high, swaps);
    return swaps;
}
 
