        perror("malloc");
        exit(1);
    }

    ret = read(fd, buf, bufsize);
    if (ret < 0) {
        perror("read");
        exit(1);
    }

    printf("Read %d bytes\n", ret);

    ret = close(fd);
    if (ret < 0) {
        perror("close");
        exit(1);
    }

    free(buf);

