#define MAX_RES 10
 
uint32_t res[MAX_RES];
uint32_t ri = 1, p = 10, count = 0;
 
void TabulateTwinPrimes(uint32_t bound) {
    if (bound < 5) return; count++;
    uint32_t cl = (bound - 1) >> 1, i = 1, j,
             limit = (uint32_t)(sqrt(bound) - 1) >> 1;
    bool comp[cl]; bool lp;
    for (j = 3; j < cl; j += 3) comp[j] = true;
    while (i < limit) {
        if (lp =!comp[i]) {
            uint32_t pr = (i << 1) + 3;
            for (j = (pr * pr - 2) >> 1; j < cl; j += pr)
                comp[j] = true;
        }
        if (!comp[++i]) {
            uint32_t pr = (i << 1) + 3;
            if (lp) {
                if (pr > p) {
                    res[ri++] = count;
                    p *= 10;
                }
                count++;
                i++;
            }
            for (j = (pr * pr - 2) >> 1; j < cl; j += pr)
                comp[j] = true; 
        }
    }
    cl--;
    while (i < cl) {
        lp =!comp[i++];
        if (!comp[i] && lp) {
            if ((i++ << 1) + 3 > p) {
                res[ri++] = count;
                p *= 10;
            }
            count++;
        }
    }
    res[ri] = count;
}
 
int main(void) {
    clock_t start = clock();
    char fmt[] = "%9lu twin primes below %13lu\n";
    TabulateTwinPrimes(1000000000);
    clock_t end = clock();
    p = 1;
    for (uint32_t j = 1; j <= ri; j++)
        printf(fmt, res[j], p *= 10);
    printf("%f sec\n", (double)(end - start) / CLOCKS_PER_SEC);
    return 0;
}

