bool check_isbn13(char *isbn) {
    int count = 0;
    int sum = 0;
 
    for (char *p = isbn; *p; p++) {
        /* skip hyphens or spaces */
        if (*p =='' || *p == '-') {
            continue;
        }
        if (*p < '0' || *p > '9') {
            return false;
        }
        if (count & 1) {
            sum += 3 * (*p - '0');
        } else {
            sum += *p - '0';
        }
        count++;
    }
 
    if (count!= 13) {
        return false;
    }
    return sum % 10 == 0;
}
 
