int decodeSingle(char letter) {
	switch(letter) {
		case 'M': return 1000;
		case 'D': return 500;
		case 'C': return 100;
		case 'L': return 50;
		case 'X': return 10;
		case 'V': return 5;
		case 'I': return 1;
		default: return 0;
	}
}

int decode(char* roman) {
	int result = 0;
	char* uRoman = roman; //case-insensitive
	for(int i = 0;i < strlen(uRoman) - 1;i++) {//loop over all but the last character
		//if this character has a lower value than the next character
		if (decodeSingle(uRoman[i]) < decodeSingle(uRoman[i+1])) {
			//subtract it
			result -= decodeSingle(uRoman[i]);
		} else {
			//add it
			result += decodeSingle(uRoman[i]);
		}
	}
	//decode the last character, which is always added
	result += decodeSingle(uRoman[strlen(uRoman)-1]);
	return result;
}

