int quickselect(int *list, int len, int k) {
    while (1) {
        // partition
        int px = len / 2;
        int pv = list[px];
        int last = len - 1;
        list[px] = list[last];
        list[last] = pv;
        int i = 0;
        for (int j = 0; j < last; j++) {
            if (list[j] < pv) {
                int tmp = list[i];
                list[i] = list[j];
                list[j] = tmp;
                i++;
            }
        }
        // select
        if (i == k) {
            return pv;
        }
        if (k < i) {
            len = i;
        } else {
            list[i] = list[last];
            list[last] = pv;
            list = list + i + 1;
            len = len - i - 1;
            k -= i + 1;
        }
    }
}
 
