def nextPerm(perm):
    size = len(perm)
    k = -1
    for i in range(size - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            k = i
            break
    if k == -1:
        return False  # last permutation
    for l in range(size - 1, k, -1):
        if perm[k] < perm[l]:
            perm[k], perm[l] = perm[l], perm[k]
            m = k + 1
            n = size - 1
            while m < n:
                perm[m], perm[n] = perm[n], perm[m]
                m += 1
                n -= 1
            break
    return True
 
def isMonotonic(lst):
    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            return False
    return True
 
