import math
import primesieve
 
def isqrt(n):
    return int(math.sqrt(n))
 
def is_semiprime(n):
    root = isqrt(n) + 1
    primes1 = primesieve.primes(root)
    count = 0
 
    for i in primes1:
        while n % i == 0:
            n //= i
            count += 1
        if n == 1:
            break
 
    if n!= 1:
        count += 1
    return count == 2
 
