class Direction(Enum):
    left = 0
    up = 1
    right = 2
    down = 3
 
def snusp(datalength, progstring):
    stack = []
    data = [0] * datalength
    dp = ipx = ipy = 0
    direction = Direction.right  # default to go to right at beginning
 
    lines = progstring.split("\n")
    lmax = max(map(len, lines))
    lines = list(map(lambda x: x.ljust(lmax), lines))
    for y, li in enumerate(lines):
        if (x := li.find("$"))!= -1:
            (ipx, ipy) = (x, y)
 
    instruction = {
        ">": lambda: dp += 1,
        "<": lambda: dp -= 1,
        "+": lambda: data[dp] += 1,
        "-": lambda: data[dp] -= 1,
        ",": lambda: data[dp] = ord(sys.stdin.read(1)),
        ".": lambda: print(chr(data[dp]), end=""),
        "/": lambda: direction = Direction((direction.value + (1 if direction.value % 2 == 0 else -1)) % 4),
        "\\": lambda: direction = Direction((direction.value + (1 if direction.value % 2 == 1 else -1)) % 4),
        "!": lambda: ipnext(),
        "?": lambda: ipnext() if data[dp] == 0 else None,
        "@": lambda: stack.append((ipx, ipy, direction)),
        "#": lambda: (ipx, ipy, direction) = stack.pop() if len(stack) > 0 else None,
        "\n": lambda: exit(data[dp])
    }
 
    def inboundsx(plus):
        return (plus and ipx < lmax) or (not plus and ipx > 0)
 
    def inboundsy(plus):
        return (plus and ipy < len(lines)) or (not plus and ipy > 0)
 
    def ipnext():
        nonlocal ipx, ipy
        if direction == Direction.right and inboundsx(True):
            ipx += 1
        elif direction == Direction.left and inboundsx(False):
            ipx -= 1
        elif direction == Direction.down and inboundsy(True):
            ipy += 1
        elif direction == Direction.up and inboundsy(False):
            ipy -= 1
 
    running = True
    while running:
        cmdcode = lines[ipy][ipx]
        if cmdcode in instruction:
            instruction[cmdcode]()
        ipnext()
 
