import time
class CountingSemaphore:
    def __init__(self, Max):
        self.lockCount = 0
        self.maxCount = Max
        self.lock = threading.Lock()
        self.cond = threading.Condition(self.lock)
    def acquire(self):
        self.lock.acquire()
        while self.lockCount >= self.maxCount:
            self.cond.wait()
        self.lockCount += 1
        self.lock.release()
    def release(self):
        self.lock.acquire()
        if self.lockCount > 0:
            self.lockCount -= 1
            self.cond.notifyAll()
        self.lock.release()
    def getCount(self):
        return self.lockCount
class Worker(threading.Thread):
    def __init__(self, coordinator, num):
        threading.Thread.__init__(self)
        self.lock = coordinator
        self.id = num
    def run(self):
        self.lock.acquire()
        print("Worker " + str(self.id) + " has acquired the lock.")
        time.sleep(2)
        self.lock.release()
