def StoogeSort(L, i, j):
    if L[j] < L[i]:
        L[i], L[j] = L[j], L[i]
    if j - i > 1:
        t = (j - i + 1) // 3
        StoogeSort(L, i, j - t)
        StoogeSort(L, i + t, j)
        StoogeSort(L, i, j - t)

