    int *data;
} HashSet;
 
HashSet *HashSet_new(int capacity) {
    HashSet *set = malloc(sizeof(HashSet));
    set->size = 0;
    set->capacity = capacity;
    set->data = malloc(capacity * sizeof(int));
    return set;
}
 
void HashSet_free(HashSet *set) {
    free(set->data);
    free(set);
}
 
int HashSet_contains(HashSet *set, int value) {
    for (int i = 0; i < set->size; i++) {
        if (set->data[i] == value) {
            return 1;
        }
    }
    return 0;
}
 
void HashSet_insert(HashSet *set, int value) {
    if (set->size == set->capacity) {
        set->capacity *= 2;
        set->data = realloc(set->data, set->capacity * sizeof(int));
    }
    set->data[set->size] = value;
    set->size++;
}
 
void HashSet_remove(HashSet *set, int value) {
    for (int i = 0; i < set->size; i++) {
        if (set->data[i] == value) {
            set->data[i] = set->data[set->size - 1];
            set->size--;
            return;
        }
    }
}
 
