bool *sieve(int limit) {
    limit++;
    // True denotes composite, false denotes prime.
    // Don't bother marking even numbers >= 4 as composite.
    bool *c = calloc(limit, sizeof(bool));
    c[0] = true;
    c[1] = true;
 
    int p = 3; // start from 3
    while (true) {
        int p2 = p * p;
        if (p2 >= limit) {
            break;
        }
        for (int i = p2; i < limit; i += 2 * p) {
            c[i] = true;
        }
        do {
            p += 2;
        } while (c[p]);
    }
    return c;
}
 
