int gcd(int a, int b) {
  a = abs(a);
  b = abs(b);

  if (b > a) {
    int temp = a;
    a = b;
    b = temp;
  }

  while (true) {
    a %= b;
    if (a == 0) { return b; }
    b %= a;
    if (b == 0) { return a; }
  }
}

