} bigint_array;
 
bigint_array *bigint_array_new(size_t size) {
    bigint_array *a = malloc(sizeof(bigint_array));
    a->data = malloc(sizeof(mpz_t) * size);
    a->size = size;
    for (size_t i = 0; i < size; i++)
        mpz_init(a->data[i]);
    return a;
}
 
void bigint_array_free(bigint_array *a) {
    for (size_t i = 0; i < a->size; i++)
        mpz_clear(a->data[i]);
    free(a->data);
    free(a);
}
 
bigint_array *cumu(int n) {
    bigint_array **cache = malloc(sizeof(bigint_array *) * (n + 1));
    cache[0] = bigint_array_new(1);
    mpz_set_ui(cache[0]->data[0], 1);
 
    for (int L = 1; L < n + 1; L++) {
        cache[L] = bigint_array_new(L + 1);
        mpz_set_ui(cache[L]->data[0], 0);
        for (int x = 1; x < L + 1; x++) {
            mpz_add(cache[L]->data[x], cache[L]->data[x - 1],
                    cache[L - x]->data[x < L - x? x : L - x]);
        }
    }
 
    bigint_array *r = cache[n];
    for (int i = 0; i < n + 1; i++)
        bigint_array_free(cache[i]);
    free(cache);
    return r;
}
 
