    bigint_array *r = cumu(n);
    bigint_array *s = bigint_array_new(n);
    for (int i = 0; i < n; i++)
        mpz_sub(s->data[i], r->data[i + 1], r->data[i]);
    bigint_array_free(r);
    return s;
}
 
