#define MAX_LINE_LEN 1024
 
typedef struct {
    char *key;
    char *val;
} fasta_t;
 
fasta_t *fasta_parse(FILE *infile)
{
    char line[MAX_LINE_LEN];
    char *key = NULL;
    char *val = NULL;
    fasta_t *fasta = NULL;
    int nfasta = 0;
    int nalloc = 0;
    while (fgets(line, MAX_LINE_LEN, infile)) {
        if (line[0] == '>') {
            if (key) {
                if (nfasta == nalloc) {
                    nalloc = nalloc? 2 * nalloc : 1;
                    fasta = realloc(fasta, nalloc * sizeof(fasta_t));
                }
                fasta[nfasta].key = key;
                fasta[nfasta].val = val;
                nfasta++;
            }
            key = strdup(line + 1);
            val = NULL;
        } else if (key) {
            if (val) {
                val = realloc(val, strlen(val) + strlen(line) + 1);
                strcat(val, line);
            } else {
                val = strdup(line);
            }
        }
    }
    if (key) {
        if (nfasta == nalloc) {
            nalloc = nalloc? 2 * nalloc : 1;
            fasta = realloc(fasta, nalloc * sizeof(fasta_t));
        }
        fasta[nfasta].key = key;
        fasta[nfasta].val = val;
        nfasta++;
    }
    return fasta;
}
 
int main(int argc, char **argv)
{
    FILE *infile = fopen(argv[1], "r");
    fasta_t *fasta = fasta_parse(infile);
    int i;
    for (i = 0; fasta[i].key; i++) {
        printf("%s: %s\n", fasta[i].key, fasta[i].val);
    }
    return 0;
}

