int **beadsort(int *array, int length) {
  int **result = malloc(sizeof(int *) * length);
  int i, j, k;
  for (i = 0; i < length; i++) {
    int *row = malloc(sizeof(int) * array[i]);
    for (j = 0; j < array[i]; j++) {
      row[j] = 1;
    }
    result[i] = row;
  }
  int max = 0;
  for (i = 0; i < length; i++) {
    if (array[i] > max) {
      max = array[i];
    }
  }
  int **columns = malloc(sizeof(int *) * max);
  for (i = 0; i < max; i++) {
    int *column = malloc(sizeof(int) * length);
    for (j = 0; j < length; j++) {
      if (i < array[j]) {
        column[j] = result[j][i];
      } else {
        column[j] = 0;
      }
    }
    columns[i] = column;
  }
  int **final = malloc(sizeof(int *) * max);
  for (i = 0; i < max; i++) {
    int *row = malloc(sizeof(int) * length);
    for (j = 0; j < length; j++) {
      int count = 0;
      for (k = 0; k < max; k++) {
        if (columns[k][j] == 1) {
          count++;
        }
      }
      row[j] = count;
    }
    final[i] = row;
  }
  return final;
}
 
