def is_prime(n):
    if n == 2 or n == 3 or n == 5 or n == 7 or n == 11 or n == 13:
        return True
    if n % 2 == 0 or n % 3 == 0 or n % 5 == 0 or n % 7 == 0 or n % 11 == 0 or n % 13 == 0:
        return False
    root = int(sqrt(n)) + 1
    for i in range(17, root, 2):
        if n % i == 0:
            return False
    return True
 
def is_emirp(n):
    aux = n
    rev_prime = 0
    while aux > 0:
        rev_prime = rev_prime * 10 + aux % 10
        aux //= 10
    if n == rev_prime:
        return False
    return is_prime(rev_prime)
 
