class Stack(object):
    def __init__(self):
        self.data = []
 
    @property
    def size(self):
        return len(self.data)
 
    @property
    def empty(self):
        return self.size == 0
 
    def push(self, element):
        self.data.append(element)
 
    def pop(self):
        if self.empty:
            raise RuntimeError("Can't pop elements from an empty stack")
        return self.data.pop()
 
    @property
    def top(self):
        if self.empty:
            raise RuntimeError("Empty stack can't have a top element")
        return self.data[-1]
 
    def clear(self):
        self.data.clear()
 
    def __str__(self):
        return str(self.data)
 
def main():
    s = Stack()
    for i in range(1, 6):
        s.push(i)
    print(s)
    print("Size of stack = {}".format(s.size))
    print("Popping: ", end="")
    for i in range(3):
        print("{} ".format(s.pop()), end="")
    print("\nRemaining on stack: {}".format(s))
    print("Top element is now {}".format(s.top))
    s.clear()
    print("After clearing, stack is {}".format("empty" if s.empty else "not empty"))
    try:
        s.pop()
    except Exception as e:
        print(e)
 
