# Arguments: predicate, maximum perimeter
# pythTripleCount :: ((Int, Int, Int) -> Bool) -> Int -> Int
def pythTripleCount(p: Callable[[int, int, int], bool], maxPerim: int) -> int:
    xs = enumFromTo(1, floor(maxPerim / 2))

    return len(
        [
            (x, y, z)
            for x in xs
            for y in xs[x:]
            for z in xs[y:]
            if x + y + z <= maxPerim
            and x * x + y * y == z * z
            and p(x, y, z)
        ]
    )


