void cumu(int n, mpz_t **cache) {
    int i, j;
    mpz_t *r;
 
    for (i = 0; i < n; i++) {
        r = cache[i];
        for (j = 1; j < i+1; j++) {
            mpz_add(r[j], r[j], r[j-1]);
        }
    }
}
 
void row(int n, mpz_t **cache) {
    int i;
    mpz_t *r;
 
    cumu(n, cache);
    r = cache[n-1];
    for (i = 0; i < n-1; i++) {
        mpz_sub(r[i], r[i+1], r[i]);
    }
}
 
