void solvePell(unsigned long long nn, mpz_t x, mpz_t y) {
    unsigned long long n = nn;
    mpz_t z, r, e1, e2, f1, f2, t, u, a, b;
    mpz_inits(x, y, z, r, e1, e2, f1, f2, t, u, a, b, NULL);
    mpz_set_ui(x, n);
    mpz_sqrt(x, x);
    mpz_set(y, x);
    mpz_set_ui(z, 1);
    mpz_lshift(r, x, 1);
 
    mpz_set_ui(e1, 1);
    mpz_init(e2);
    mpz_init(f1);
    mpz_set_ui(f2, 1);
 
    mpz_tdiv_q(t, r, z);
    mpz_mul(t, t, z);
    mpz_sub(y, t, y);
    mpz_mul(t, y, y);
    mpz_sub(t, n, t);
    mpz_tdiv_q(z, t, z);
    mpz_add(t, x, y);
    mpz_tdiv_q(r, t, z);
    mpz_set(u, e1);
    mpz_set(e1, e2);
    mpz_mul(t, r, e2);
    mpz_add(e2, t, u);
    mpz_set(u, f1);
    mpz_set(f1, f2);
    mpz_mul(t, r, f2);
    mpz_add(f2, t, u);
    mpz_mul(t, x, f2);
    mpz_add(a, e2, t);
    mpz_set(b, f2);
    mpz_mul(t, a, a);
    mpz_mul(u, n, b);
    mpz_mul(u, u, b);
    mpz_sub(t, t, u);
    if (mpz_cmp_ui(t, big1) == 0) {
        mpz_set(x, a);
        mpz_set(y, b);
    } else {
        solvePell(n, x, y);
    }
    mpz_clears(z, r, e1, e2, f1, f2, t, u, a, b, NULL);
}
 
