#include <stdio.h>
#include <math.h>
 
typedef struct {
    double x;
    double y;
} Pt;
 
#define C 7
 
Pt zero = {.x = INFINITY,.y = INFINITY };
 
int isZero(Pt p) {
    return p.x > 1e20 || p.x < -1e20;
}
 
Pt dbl(Pt p) {
    if (isZero(p)) return p;
    double l = 3.0 * p.x * p.x / (2.0 * p.y);
    double t = l * l - 2.0 * p.x;
    return (Pt) {.x = t,.y = l * (p.x - t) - p.y };
}
 
Pt neg(Pt p) {
    return (Pt) {.x = p.x,.y = -p.y };
}
 
Pt add(Pt p, Pt q) {
    if (p.x == q.x && p.y == q.y) return dbl(p);
    if (isZero(p)) return q;
    if (isZero(q)) return p;
    double l = (q.y - p.y) / (q.x - p.x);
    double t = l * l - p.x - q.x;
    return (Pt) {.x = t,.y = l * (p.x - t) - p.y };
}
 
Pt mul(Pt p, int n) {
    Pt r = zero;
    Pt q = p;
    int i = 1;
    while (i <= n) {
        if ((i & n)!= 0) r = add(r, q);
        q = dbl(q);
        i = i << 1;
    }
    return r;
}
 
Pt toPt(double x) {
    return (Pt) {.x = cbrt(x * x - C),.y = x };
}
 
void printPt(Pt p) {
    if (isZero(p)) printf("Zero");
    else printf("(%.3f, %.3f)", p.x, p.y);
}
 
int main(int argc, char **argv) {
