    printf("b         = "); printPt(b); printf("\n");
    printf("c = a + b = "); printPt(c); printf("\n");
    printf("d = -c    = "); printPt(d); printf("\n");
    printf("c + d     = "); printPt(add(c, d)); printf("\n");
    printf("a + b + d = "); printPt(add(add(a, b), d)); printf("\n");
    printf("a * 12345 = "); printPt(mul(a, 12345)); printf("\n");
