    uint32_t operator()()
    {
      uint32_t checksum = n++;
 
      for (int i = 0; i < 8; ++i)
        checksum = (checksum >> 1) ^ ((checksum & 0x1u)? reversed_polynomial : 0);
 
      return checksum;
    }
 
    unsigned n = 0;
  };
 
  uint32_t* table = (uint32_t*)malloc(sizeof(uint32_t) * 256);
  for (int i = 0; i < 256; i++)
    table[i] = byte_checksum()();
 
  return table;
}
 
// Calculates the CRC for any sequence of values. (You could use type traits and a
// static assert to ensure the values can be converted to 8 bits.)
uint32_t crc(char* first, char* last)
{
  // Generate lookup table only on first use then cache it - this is thread-safe.
  static uint32_t* table = generate_crc_lookup_table();
 
  // Calculate the checksum - make sure to clip to 32 bits, for systems that don't
  // have a true (fast) 32-bit type.
  uint32_t checksum = 0xFFFFFFFFuL;
  for (char* i = first; i < last; i++)
    checksum = table[(checksum ^ *i) & 0xFFu] ^ (checksum >> 8);
 
  return checksum;
}
 
