int *CastOut(int base, int start, int end) {
    int *ran = (int *)malloc(sizeof(int) * (base - 1));
    int i, j, x, k, len = 0;
    for (i = 0; i < base - 1; i++) {
        if (i % (base - 1) == (i * i) % (base - 1)) {
            ran[len++] = i;
        }
    }
    x = start / (base - 1);
    int *result = (int *)malloc(sizeof(int) * (end - start + 1));
    int *p = result;
    while (1) {
        for (i = 0; i < len; i++) {
            k = (base - 1) * x + ran[i];
            if (k < start) {
                continue;
            }
            if (k > end) {
                return result;
            }
            *p++ = k;
        }
        x++;
    }
}
 
