    printf("%s\n", AsString(result, 255));
    free(result);
    result = CastOut(10, 1, 99);
    printf("%s\n", AsString(result, 99));
    free(result);
    result = CastOut(17, 1, 288);
    printf("%s\n", AsString(result, 288));
    free(result);
