char *collapse(char *str) {
  int i, j;
  for (i = 0; i < strlen(str); i++) {
    while (str[i] == str[i+1]) {
      for (j = i; j < strlen(str); j++) {
        str[j] = str[j+1];
      }
    }
  }
  return str;
}
 
