// that do not form valid UTF-8.  return value is UTF-8.
char *reverseCodePoints(char *s) {
    int len = strlen(s);
    wchar_t *r = malloc(len * sizeof(wchar_t));
    int start = len;
    for (int i = 0; i < len; i++) {
        // quietly skip invalid UTF-8
        if (s[i]!= 0xFFFD) {
            start--;
            r[start] = s[i];
        }
    }
    r[start] = '\0';
    return (char *)r;
