import math
 
def isZumkeller(n):
    #  numbers congruent to 6 or 12 modulo 18 are Zumkeller numbers
    if n % 18 == 6 or n % 18 == 12:
        return True
 
    divisors = getDivisors(n)        
    divisorSum = sum(divisors)
 
    #  divisor sum cannot be odd
    if divisorSum % 2 == 1:
        return False
 
    # numbers where n is odd and the abundance is even are Zumkeller numbers
    abundance = divisorSum - 2 * n
    if n % 2 == 1 and abundance > 0 and abundance % 2 == 0:
        return True
 
    divisors.sort()
    j = len(divisors) - 1
    sum = divisorSum/2
 
    #  Largest divisor larger than sum - then cannot partition and not Zumkeller number
    if divisors[j] > sum:
        return False
 
    return canPartition(j, divisors, sum, [0, 0])
 
def canPartition(j, divisors, sum, buckets):
    if j < 0:
        return True
    for i in range(2):
        if buckets[i] + divisors[j] <= sum:
            buckets[i] += divisors[j]
            if canPartition(j-1, divisors, sum, buckets):
                return True
            buckets[i] -= divisors[j]
        if buckets[i] == 0:
            break
    return False
 
def getDivisors(number):
    divisors = []
    sqrt = int(math.sqrt(number))
    for i in range(1, sqrt + 1):
        if number % i == 0:
            divisors.append(i)
            div = number / i
            if div!= i:
                divisors.append(div)
    return divisors
 
