# Trie structure of sorts
class word:
	def __init__(self, w):
		self.w = w
		self.next = None
 
class node:
	def __init__(self):
		self.down = [None] * 10
		self.list = [None] * 10
 
def deranged(s1, s2):
	for i in range(len(s1)):
		if s1[i] == s2[i]:
			return False
	return True
 
def count_letters(s, c):
	for i in range(len(c)):
		c[i] = 0
	for i in range(len(s)):
		if s[i] < 'a' or s[i] > 'z':
			return 0
		c[char_to_idx[ord(s[i])]] += 1
	return len(s)
 
def insert(root, s, cnt):
	n = None
	w = None
	v = None
	for i in range(25):
		if not root.down[cnt[i]]:
			root.down[cnt[i]] = node()
		root = root.down[cnt[i]]
	w = word(s)
	w.next = root.list[cnt[25]]
	root.list[cnt[25]] = w
	v = w.next
	while v:
		if deranged(w.w, v.w):
			return v.w
		v = v.next
	return None
 
