import math
 
def fact(n):
	if n < 1:
		return 0
	r = 1
	for i in range(2, n+1):
		r *= i
	return r
 
def perm(n, k):
	r = fact(n)
	r //= fact(n-k)
	return r
 
def comb(n, r):
	if r > n:
		return 0
	if r == n:
		return 1
	c = fact(n)
	den = fact(n-r)
	den *= fact(r)
	c //= den
	return c
 
