def yellowstone(n):
    m = [False] * (n + 1)
    a = [0] * (n + 1)
    for i in range(1, 4):
        a[i] = i
        m[i] = True
    min = 4
    for c in range(4, n + 1):
        for i in range(min, n + 1):
            if not m[i] and gcd(a[c - 1], i) == 1 and gcd(a[c - 2], i) > 1:
                a[c] = i
                m[i] = True
                if i == min:
                    min += 1
                break
    return a[1:]
 
