from math import sqrt
 
def sieve(limit):
    primes = [2]
    c = [False] * (limit + 1) # composite = True
    # no need to process even numbers > 2
    p = 3
    while True:
        p2 = p * p
        if p2 > limit: break
        for i in range(p2, limit + 1, 2 * p): c[i] = True
        while True:
            p += 2
            if not c[p]: break
    for i in range(3, limit + 1, 2):
        if not c[i]:
            primes.append(i)
 
    return primes
 
def squareFree(r):
    primes = sieve(int(sqrt(r[-1])))
    results = []
    for i in r:
        for p in primes:
            p2 = p * p
            if p2 > i: break
            if i % p2 == 0: break
        else:
            results.append(i)
    return results
 
