# pancake sort template (calls predicate to determine order)
def pancake_sort(first, last, order):
    if len(first) < 2:
        return # no sort needed
 
    for i in range(len(first)):
        mid = max(first, key=order)
        if mid == last - 1:
            continue # no flips needed
        if first!= mid:
            first.reverse() # flip element to front
        first.reverse() # flip front to final position
 
