def stoogeSort(array, i, j):
    if j == None:
        j = len(array) - 1
    if i == None:
        i = 0
    if array[j] < array[i]:
        aux = array[i]
        array[i] = array[j]
        array[j] = aux
    if j - i > 1:
        t = int((j - i + 1) / 3)
        stoogeSort(array, i, j-t)
        stoogeSort(array, i+t, j)
        stoogeSort(array, i, j-t)

def subarray_sum(arr):
    max, slice = 0, []
    for i in range(len(arr)):
        for j in range(i, len(arr)):
            sum = sum(arr[i:j+1])
            if sum > max:
                max, slice = sum, arr[i:j+1]
    return [max, slice]

