class Complex:
    def __init__(self, r, i):
        self.real = r
        self.imag = i

    def add(self, b):
        return Complex(self.real + b.real, self.imag + b.imag)

    def mult(self, b):
        return Complex(self.real * b.real - self.imag * b.imag,
                       self.real * b.imag + self.imag * b.real)

    def inv(self):
        denom = self.real * self.real + self.imag * self.imag
        return Complex(self.real / denom, -self.imag / denom)

    def neg(self):
        return Complex(-self.real, -self.imag)

    def conj(self):
        return Complex(self.real, -self.imag)

    def __str__(self):
        return str(self.real) + " + " + str(self.imag) + " * i"

