void tree(int root, Stem *head) {
    Stem *tail = head;
    while (tail!= NULL) {
        printf("%s", tail->str);
        if (tail->next == NULL) break;
        tail = tail->next;
    }
    printf("--%d\n", root);
    if (root <= 1) return;
    if (tail!= NULL && tail->str == SLAST) tail->str = SNONE;
    if (tail == NULL) {
        head = col;
        tail = head;
    }
    else {
        tail->next = col;
    }
    int root2 = root;
    while (root2!= 0) { // make a tree by doing something random
        int r = 1 + rand() % root2;
        root2 -= r;
        col->str = (root2!= 0)? SDOWN : SLAST;
        tree(r, head);
    }
    tail->next = NULL;
}
 
