#define A 12
 
double gammaInc_Q(double a, double x)
{
  double a1, a2, y, h, hh, sum, t;
  int n, j;
  double f0(double t) { return pow(t, a1) * exp(-t); }
  double df0(double t) { return (a1-t) * pow(t, a2) * exp(-t); }
 
  a1 = a-1;
  a2 = a-2;
  y = a1;
  while (f0(y)*(x-y) > 2.0e-8 && y < x) y += 0.3;
  if (y > x) y = x;
 
  h = 3.0e-4;
  n = (int)(y/h);
  h = y/n;
  hh = 0.5 * h;
  sum = 0;
  for (j=n-1; j>=0; j--) {
    t = h * j;
    sum += f0(t) + hh * df0(t);
  }
  return h * sum / gamma_spounge(a);
}
 
double COEF[A];
 
double gamma_spounge(double z)
{
  int k;
  double k1_factrl, accm;
 
  k1_factrl = 1.0;
  COEF[0] = sqrt(2.0*M_PI);
  for (k=1; k<A; k++) {
    COEF[k] = exp(A-k) * pow(A-k, k-0.5) / k1_factrl;
    k1_factrl *= -k;
  }
 
  accm = 0;
  for (k=0; k<A; k++) accm += COEF[k] / (z+k);
  return accm * exp(-(z+A)) * pow(z+A, z+0.5) / z;
}
 
double chi2UniformDistance(int dataSet[], int size)
{
  int i;
  double expected, distance;
 
  expected = 0;
  for (i=0; i<size; i++) expected += dataSet[i];
  expected /= size;
 
  distance = 0;
  for (i=0; i<size; i++) {
    double d = dataSet[i] - expected;
    distance += d*d;
  }
  return distance / expected;
}
 
double chi2Probability(int dof, double distance)
{
  return 1.0 - gammaInc_Q(0.5*dof, 0.5*distance);
}
 
int chi2IsUniform(int dataSet[], int size, double significance)
{
  int dof = size - 1;
  double dist = chi2UniformDistance(dataSet, size);
  return chi2Probability(dof, dist) > significance;
}
 
