typedef struct {
    double x;
    double y;
} Point;
 
Point Point_init(double x, double y) {
    Point p;
    p.x = x;
    p.y = y;
    return p;
}
 
Point Point_copy(Point p) {
    return Point_init(p.x, p.y);
}
 
int Point_is_zero(Point p) {
    return p.x > 1e20 || p.x < -1e20;
}
 
Point Point_neg(Point p) {
    return Point_init(p.x, -p.y);
}
 
Point Point_dbl(Point p) {
    if (Point_is_zero(p)) {
        return Point_copy(p);
    }
    double L = (3 * p.x * p.x) / (2 * p.y);
    double x = L * L - 2 * p.x;
    return Point_init(x, L * (p.x - x) - p.y);
}
 
Point Point_add(Point p, Point q) {
    if (p.x == q.x && p.y == q.y) {
        return Point_dbl(p);
    }
    if (Point_is_zero(p)) {
        return Point_copy(q);
    }
    if (Point_is_zero(q)) {
        return Point_copy(p);
    }
    double L = (q.y - p.y) / (q.x - p.x);
    double x = L * L - p.x - q.x;
    return Point_init(x, L * (p.x - x) - p.y);
}
 
Point Point_mul(Point p, int n) {
    Point r = Point_init(0, 0);
    int i = 1;
    while (i <= n) {
        if (i & n) {
            r = Point_add(r, p);
        }
        p = Point_dbl(p);
        i <<= 1;
    }
    return r;
}
 
void Point_show(char *s, Point p) {
    printf("%s (%.3f, %.3f)\n", s, p.x, p.y);
}
 
Point from_y(double y) {
    double n = y * y - 7;
    double x = pow(n, 1./3);
    if (n < 0) {
        x = -pow(-n, 1./3);
    }
    return Point_init(x, y);
}
 
