bool sameDigits(int n, int b) {
    int f = n % b;
    n /= b;
    while (n > 0) {
        if (n % b!= f) {
            return false;
        }
        n /= b;
    }
    return true;
}
 
bool isBrazilian(int n) {
    if (n < 7) {
        return false;
    }
    if (n % 2 == 0 && n >= 8) {
        return true;
    }
    for (int b = 2; b < n - 1; b++) {
        if (sameDigits(n, b)) {
            return true;
        }
    }
    return false;
}
 
bool isPrime(int n) {
    switch (n) {
    case 0:
    case 1:
        return false;
    case 2:
    case 3:
        return true;
    default:
        int d = 5;
        while (d * d <= n) {
            if (n % d == 0) {
                return false;
            }
            d += 2;
            if (n % d == 0) {
                return false;
            }
            d += 4;
        }
        return true;
    }
}
 
