void extend_sequences(int n) {
	int current = fmax(R[R[0]],S[S[0]]);
	int i;
	while (R[0] <= n || S[0] <= n) {
		i = fmin(R[0], S[0]) - 1;
		current += 1;
		if (current == R[i] + S[i]) {
			R[0] += 1;
			R[R[0]] = current;
		} else {
			S[0] += 1;
			S[S[0]] = current;
		}
	}
}
 
