#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <semaphore.h>

typedef struct {
    int lockCount;
    int maxCount;
    sem_t lock;
} CountingSemaphore;

CountingSemaphore* CountingSemaphore_new(int max) {
    CountingSemaphore* this = malloc(sizeof(CountingSemaphore));
    this->lockCount = 0;
    this->maxCount = max;
    sem_init(&this->lock, 0, 1);
    return this;
}

void CountingSemaphore_acquire(CountingSemaphore* this) {
    sem_wait(&this->lock);
    while (this->lockCount >= this->maxCount) {
        sem_post(&this->lock);
        sem_wait(&this->lock);
    }
    this->lockCount++;
    sem_post(&this->lock);
}

void CountingSemaphore_release(CountingSemaphore* this) {
    sem_wait(&this->lock);
    if (this->lockCount > 0) {
        this->lockCount--;
        sem_post(&this->lock);
    }
}

int CountingSemaphore_getCount(CountingSemaphore* this) {
    return this->lockCount;
}

typedef struct {
    CountingSemaphore* lock;
    int id;
} Worker;

Worker* Worker_new(CountingSemaphore* coordinator, int num) {
    Worker* this = malloc(sizeof(Worker));
    this->lock = coordinator;
    this->id = num;
    return this;
}

void* Worker_run(void* arg) {
    Worker* this = (Worker*)arg;
    CountingSemaphore_acquire(this->lock);
    printf("Worker %d has acquired the lock.\n", this->id);
    sleep(2);
    CountingSemaphore_release(this->lock);
    return NULL;
}

int main() {
    CountingSemaphore* lock = CountingSemaphore_new(3);
    Worker* crew[5];
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        crew[i] = Worker_new(lock, i);
        pthread_create(&threads[i], NULL, Worker_run, crew[i]);
    }
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}

