unsigned long long ipow(unsigned long long base, unsigned long long exp) {
    unsigned long long result = 1;
    while (exp) {
        if (exp & 1) {
            result *= base;
        }
        exp >>= 1;
        base *= base;
    }
    return result;
}
 
