double statistic(double *ab, int nab, double *a, int na) {
  double sumab = 0, suma = 0;
  int i;
  for (i = 0; i < nab; i++) sumab += ab[i];
  for (i = 0; i < na; i++) suma += a[i];
  return suma / na - (sumab - suma) / (nab - na);
}
 
double permutationTest(double *a, int na, double *b, int nb) {
  double *ab = malloc((na + nb) * sizeof(double));
  int i;
  for (i = 0; i < na; i++) ab[i] = a[i];
  for (i = 0; i < nb; i++) ab[i + na] = b[i];
  double tobs = statistic(ab, na + nb, a, na);
  int under = 0, count = 0;
  for (i = 0; i < (1 << nb); i++) {
    double *perm = malloc(na * sizeof(double));
    int j, k = 0;
    for (j = 0; j < na + nb; j++) {
      if (i & (1 << j)) perm[k++] = ab[j];
    }
    if (statistic(ab, na + nb, perm, na) <= tobs) under++;
    count++;
    free(perm);
  }
  free(ab);
  return under * 100.0 / count;
}
 
