#define MAX_PRIME 15500000
 
int *sieve(int n)
{
    int i, k, t, v, d, s;
    int *comps = calloc(n + 1, sizeof(int));
    int *primes = calloc(n + 1, sizeof(int));
    int *p = primes;
    *p++ = 2;
    k = (n + 1) >> 1;
    t = 1;
    v = 1;
    d = 1;
    s = 1;
    for (i = 1; t < k; t = ((++i + (s += d += 2)) << 1) - d - 2)
        while ((t += d + 2) < k)
            comps[t] = 1;
    for (v = 1; v < k; v++)
        if (!comps[v])
            *p++ = (v << 1) + 1;
    return primes;
}
 
