char **ms(char *txt, char **sep, int nsep) {
    char **ans = malloc(sizeof(char *) * 100);
    int nans = 0;
    while (*txt) {
        char *sepMatch = NULL;
        int posMatch = strlen(txt);
        for (int i = 0; i < nsep; i++) {
            char *p = strstr(txt, sep[i]);
            if (p && p - txt < posMatch) {
                sepMatch = sep[i];
                posMatch = p - txt;
            }
        }
        ans[nans] = malloc(posMatch + 1);
        strncpy(ans[nans], txt, posMatch);
        ans[nans][posMatch] = '\0';
        nans++;
        txt += posMatch + strlen(sepMatch);
    }
    ans[nans] = NULL;
    return ans;
}
 
