// Returns map from sum of faces to number of ways it can happen
struct map {
    uint32_t *key;
    uint32_t *value;
    size_t size;
};
 
struct map *get_totals(uint32_t dice, uint32_t faces) {
    struct map *result = malloc(sizeof(struct map));
    result->key = malloc(sizeof(uint32_t) * (faces + 1));
    result->value = malloc(sizeof(uint32_t) * (faces + 1));
    result->size = faces + 1;
    for (uint32_t i = 1; i <= faces; ++i) {
        result->key[i] = i;
        result->value[i] = 1;
    }
    for (uint32_t d = 2; d <= dice; ++d) {
        struct map *tmp = malloc(sizeof(struct map));
        tmp->key = malloc(sizeof(uint32_t) * (faces * d + 1));
        tmp->value = malloc(sizeof(uint32_t) * (faces * d + 1));
        tmp->size = faces * d + 1;
        for (uint32_t i = 0; i < tmp->size; ++i) {
            tmp->key[i] = 0;
            tmp->value[i] = 0;
        }
        for (uint32_t i = 0; i < result->size; ++i) {
            for (uint32_t j = 1; j <= faces; ++j) {
                tmp->key[result->key[i] + j] += result->value[i];
            }
        }
        free(result->key);
        free(result->value);
        free(result);
        result = tmp;
    }
    return result;
}
 
double probability(uint32_t dice1, uint32_t faces1, uint32_t dice2, uint32_t faces2) {
    struct map *totals1 = get_totals(dice1, faces1);
    struct map *totals2 = get_totals(dice2, faces2);
    double wins = 0;
    for (uint32_t i = 0; i < totals1->size; ++i) {
        for (uint32_t j = 0; j < totals2->size; ++j) {
            if (totals2->key[j] >= totals1->key[i])
                break;
            wins += totals1->value[i] * totals2->value[j];
        }
    }
    double total = pow(faces1, dice1) * pow(faces2, dice2);
    return wins/total;
}
 
int main() {
    printf("%.10f\n", probability(9, 4, 6, 6));
    printf("%.10f\n", probability(5, 10, 6, 7));
    return 0;
}

