void Flip(List *list, int length, int num){
  for(int i = 0; i < --num; i++){
    int swap = list->arr[i];
    list->arr[i] = list->arr[num];
    list->arr[num] = swap;
  }
}
void Sort(List *list){
  if(list->len < 2)
    return;
  int i, a, max_num_pos;
  for(i = list->len; i > 1; i--){
    max_num_pos = 0;
    for(a = 0; a < i; a++){
      if(list->arr[a] > list->arr[max_num_pos])
        max_num_pos = a;
    }
    if(max_num_pos == i - 1)
      continue;
    if(max_num_pos > 0)
      Flip(list, list->len, max_num_pos + 1);
    Flip(list, list->len, i);
  }
  return;
}

int main(){
