from math import sqrt
 
class Approx:
    def __init__(self, ν, σ=0.0):
        self.ν = ν
        self.σ = σ
 
    def __str__(self):
        return f"{self.ν} ±{self.σ}"
 
    def __add__(self, a):
        if isinstance(a, Approx):
            return Approx(self.ν + a.ν, sqrt(self.σ * self.σ + a.σ * a.σ))
        else:
            return Approx(self.ν + a, self.σ)
 
    def __sub__(self, a):
        if isinstance(a, Approx):
            return Approx(self.ν - a.ν, sqrt(self.σ * self.σ + a.σ * a.σ))
        else:
            return Approx(self.ν - a, self.σ)
 
    def __mul__(self, a):
        if isinstance(a, Approx):
            v = self.ν * a.ν
            return Approx(v, sqrt(v * v * self.σ * self.σ / (self.ν * self.ν) + a.σ * a.σ / (a.ν * a.ν)))
        else:
            return Approx(self.ν * a, abs(a * self.σ))
 
    def __truediv__(self, a):
        if isinstance(a, Approx):
            v = self.ν / a.ν
            return Approx(v, sqrt(v * v * self.σ * self.σ / (self.ν * self.ν) + a.σ * a.σ / (a.ν * a.ν)))
        else:
            return Approx(self.ν / a, abs(a * self.σ))
 
    def pow(self, d):
        v = pow(self.ν, d)
        return Approx(v, abs(v * d * self.σ / self.ν))
 
