def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    if n % 3 == 0:
        return n == 3
    p = 5
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
        if n % p == 0:
            return False
        p += 4
    return True
 
def is_left_truncatable(p):
    n = 10
    q = p
    while p > n:
        if not is_prime(p % n) or q == p % n:
            return False
        q = p % n
        n *= 10
    return True
 
def is_right_truncatable(p):
    q = p / 10
    while q > 0:
        if not is_prime(q):
            return False
        q /= 10
    return True
 
