def ρ(x, y, r, i, n):
    if n < 0:
        return 0
    if n == 0:
        return y[i]

    idx = (N - 1 - n) * (N - n) // 2 + i
    if r[idx]!= r[idx]:
        r[idx] = (x[i] - x[i + n]) / (ρ(x, y, r, i, n - 1) - ρ(x, y, r, i + 1, n - 1)) + ρ(x, y, r, i + 1, n - 2)
    return r[idx]

def thiele(x, y, r, xin, n):
    if n > N - 1:
        return 1
    return ρ(x, y, r, 0, n) - ρ(x, y, r, 0, n - 2) + (xin - x[n]) / thiele(x, y, r, xin, n + 1)

