Cell = namedtuple('Cell', 'value adj')
 
class Board(object):
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.board = [[Cell(0, []) for _ in range(cols)] for _ in range(rows)]
        self.format = ' %{}d'.format(rows * cols)
        self.end = rows * cols
        self.set_adjacents()
 
    def set_adjacents(self):
        for i in range(self.rows):
            for j in range(self.cols):
                self.board[i][j].adj = [self.board[i + di][j + dj]
                                        for di, dj in ADJACENT
                                        if 0 <= i + di < self.rows and 0 <= j + dj < self.cols]
 
    def solve(self, sx, sy):
        if (self.rows * self.cols) % 2 == 1 and (sx + sy) % 2 == 1:
            print('No solution')
        else:
            print(self.to_s() if self.board[sx][sy].try_move(1) else 'No solution')
 
    def to_s(self):
        return '\n'.join(''.join(self.format % self.board[i][j].value
                                for j in range(self.cols))
                         for i in range(self.rows))
 
    def try_move(self, seq_num):
        self.value = seq_num
        if seq_num == self.end:
            return True
        for cell in sorted(chain.from_iterable(self.board), key=attrgetter('wdof')):
            if cell.value == 0 and cell.try_move(seq_num + 1):
                return True
        self.value = 0
        return False
 
    @property
    def wdof(self):
        return sum(1 for cell in self.adj if cell.value == 0)
 
