def sieve(limit):
    # True denotes composite, false denotes prime.
    # Only interested in odd numbers >= 3
    c = [False] * limit
    for i in range(3, limit // 3, 2):
        if not c[i] and chowla(i) == 0:
            for j in range(3 * i, limit, 2 * i):
                c[j] = True
    return c
 
