def primeGenerator(num, showPrimes):
  i = 0
  arr = []
  def isPrime(num):
    if num <= 16:
      return (num == 2 or num == 3 or num == 5 or num == 7 or num == 11 or num == 13)
    if num % 2 == 0 or num % 3 == 0 or num % 5 == 0 or num % 7 == 0:
      return False
    for i in range(10, i * i <= num, 10):
      if num % (i + 1) == 0:
        return False
      if num % (i + 3) == 0:
        return False
      if num % (i + 7) == 0:
        return False
      if num % (i + 9) == 0:
        return False
    return True
  if type(num) == int:
    for i in range(0, arr.length < num, i):
      if isPrime(i):
        arr.append(i)
    if showPrimes:
      return arr
    else:
      return arr.pop()
  if isinstance(num, list):
    for i in range(num[0], i <= num[1], i):
      if isPrime(i):
        arr.append(i)
    if showPrimes:
      return arr
    else:
