    bbs->width = width;
    bbs->height = height;
    bbs->data = malloc(width * height * 3);
    return bbs;
}
 
void fill(BasicBitmapStorage *bbs, int r, int g, int b) {
    int i;
    for (i = 0; i < bbs->width * bbs->height * 3; i += 3) {
        bbs->data[i] = r;
        bbs->data[i + 1] = g;
        bbs->data[i + 2] = b;
    }
}
 
void setPixel(BasicBitmapStorage *bbs, int x, int y, int r, int g, int b) {
    int i = (y * bbs->width + x) * 3;
    bbs->data[i] = r;
    bbs->data[i + 1] = g;
    bbs->data[i + 2] = b;
}
 
void getPixel(BasicBitmapStorage *bbs, int x, int y, int *r, int *g, int *b) {
    int i = (y * bbs->width + x) * 3;
    *r = bbs->data[i];
    *g = bbs->data[i + 1];
    *b = bbs->data[i + 2];
}
 
void writePPM(BasicBitmapStorage *bbs, const char *filename) {
    FILE *f = fopen(filename, "wb");
    if (f == NULL) {
        fprintf(stderr, "Error opening file '%s'\n", filename);
        exit(1);
    }
    fprintf(f, "P6\n%d %d\n255\n", bbs->width, bbs->height);
    fwrite(bbs->data, 1, bbs->width * bbs->height * 3, f);
    fclose(f);
}
 
