#include <stdio.h>
#include <stdlib.h>
#include <math.h>
 
long mod(long x, long y) {
    long m = x % y;
    if (m < 0) {
        if (y < 0) {
            m -= y;
        } else {
            m += y;
        }
    }
    return m;
}
 
typedef struct {
    // first generator
    long a1[3];
    long m1;
    long x1[3];
 
    // second generator
    long a2[3];
    long m2;
    long x2[3];
 
    long d;
} RNG;
 
void seed(RNG *rng, long state) {
    rng->x1[0] = state;
    rng->x1[1] = 0;
    rng->x1[2] = 0;
    rng->x2[0] = state;
    rng->x2[1] = 0;
    rng->x2[2] = 0;
}
 
long nextInt(RNG *rng) {
    long x1i = mod(rng->a1[0] * rng->x1[0] + rng->a1[1] * rng->x1[1] + rng->a1[2] * rng->x1[2], rng->m1);
    long x2i = mod(rng->a2[0] * rng->x2[0] + rng->a2[1] * rng->x2[1] + rng->a2[2] * rng->x2[2], rng->m2);
    long z = mod(x1i - x2i, rng->m1);
 
    // keep last three values of the first generator
    rng->x1[0] = x1i;
    rng->x1[1] = rng->x1[0];
    rng->x1[2] = rng->x1[1];
    // keep last three values of the second generator
    rng->x2[0] = x2i;
    rng->x2[1] = rng->x2[0];
    rng->x2[2] = rng->x2[1];
 
    return z + 1;
}
 
double nextFloat(RNG *rng) {
    return (double)nextInt(rng) / rng->d;
}
 
int main() {
    RNG rng;
    rng.a1[0] = 0;
    rng.a1[1] = 1403580;
    rng.a1[2] = -810728;
    rng.m1 = (1L << 32) - 209;
    rng.a2[0] = 527612;
    rng.a2[1] = 0;
    rng.a2[2] = -1370589;
    rng.m2 = (1L << 32) - 22853;
    rng.d = rng.m1 + 1;
 
    seed(&rng, 1234567);
    printf("%ld\n", nextInt(&rng));
    printf("%ld\n", nextInt(&rng));
    printf("%ld\n", nextInt(&rng));
    printf("%ld\n", nextInt(&rng));
    printf("%ld\n", nextInt(&rng));
    printf("\n");
 
    int counts[5] = {0};
    seed(&rng, 987654321);
    for (int i = 0; i < 100000; i++) {
        int v = floor(nextFloat(&rng) * 5.0);
        counts[v]++;
    }
    for (int i = 0; i < 5; i++) {
        printf("%d: %d\n", i, counts[i]);
    }
 
    return 0;
}

