bool is_prime(unsigned int n) {
    if (n < 2) {
        return false;
    }
    if (n % 2 == 0) {
        return n == 2;
    }
    if (n % 3 == 0) {
        return n == 3;
    }
    unsigned int p = 5;
    while (p * p <= n) {
        if (n % p == 0) {
            return false;
        }
        p += 2;
        if (n % p == 0) {
            return false;
        }
        p += 4;
    }
    return true;
}
 
bool is_magnanimous(unsigned int n) {
    unsigned int p = 10;
    while (n >= p) {
        if (!is_prime(n % p + n / p)) {
            return false;
        }
        p *= 10;
    }
    return true;
}
 
int main() {
    unsigned int m = 0;
    unsigned int i = 0;
    unsigned int n = 0;
    printf("First 45 magnanimous numbers:\n");
    while (i < 45) {
        if (is_magnanimous(m)) {
            if (i > 0 && i % 15 == 0) {
                printf("\n");
            }
            printf("%3u ", m);
            i++;
        }
