#define SQRT3_2 0.86602540378444
 
typedef struct {
    double x;
    double y;
    int angle;
} Cursor;
 
Cursor *new_cursor(double x, double y) {
    Cursor *cursor = malloc(sizeof(Cursor));
    cursor->x = x;
    cursor->y = y;
    cursor->angle = 0;
    return cursor;
}
 
void turn(Cursor *cursor, int angle) {
    cursor->angle = (cursor->angle + angle) % 360;
}
 
void draw_line(Cursor *cursor, double length) {
    double theta = cursor->angle * M_PI / 180.0;
    cursor->x += length * cos(theta);
    cursor->y += length * sin(theta);
}
 
void curve(FILE *file, int order, double length, Cursor *cursor, int angle) {
    if (order == 0) {
        draw_line(cursor, length);
        return;
    }
    curve(file, order - 1, length / 2.0, cursor, -angle);
    turn(cursor, angle);
    curve(file, order - 1, length / 2.0, cursor, angle);
    turn(cursor, angle);
    curve(file, order - 1, length / 2.0, cursor, -angle);
}
 
void write_sierpinski_arrowhead(const char *file, int size, int order) {
    double margin = 20.0;
    double side = (double)size - 2.0 * margin;
    double y = 0.5 * (double)size + 0.5 * SQRT3_2 * side;
    double x = margin;
    Cursor *cursor = new_cursor(x, y);
    if (order & 1) {
        turn(cursor, -60);
    }
    fprintf(file, "<path d=\"M %f %f ", x, y);
    curve(file, order, side, cursor, 60);
    fprintf(file, "\" fill=\"none\" stroke=\"black\" stroke-width=\"1\" />\n");
}
 
int main() {
    FILE *file = fopen("sierpinski_arrowhead.svg", "w");
    fprintf(file, "<svg width=\"600\" height=\"600\" xmlns=\"http://www.w3.org/2000/svg\">\n");
    fprintf(file, "<rect width=\"100%%\" height=\"100%%\" fill=\"white\" />\n");
    write_sierpinski_arrowhead(file, 600, 8);
    fprintf(file, "</svg>\n");
    fclose(file);
}

