int numPrimeFactors(unsigned int x)
{
	unsigned int p = 2;
	int pf = 0;
	if (x == 1) {
		return 1;
	}
	while (1) {
		if ((x % p) == 0) {
			pf++;
			x /= p;
			if (x == 1) {
				return pf;
			}
		} else {
			p++;
		}
	}
}
 
void primeFactors(unsigned int x, unsigned int *arr)
{
	unsigned int p = 2;
	int pf = 0;
	if (x == 1) {
		arr[pf] = 1;
		return;
	}
	while (1) {
		if ((x % p) == 0) {
			arr[pf] = p;
			pf++;
			x /= p;
			if (x == 1) {
				return;
			}
		} else {
			p++;
		}
	}
}
 
unsigned int sumDigits(unsigned int x)
{
	unsigned int sum = 0;
	while (x!= 0) {
		sum += x % 10;
		x /= 10;
	}
	return sum;
}
 
unsigned int sumFactors(unsigned int *arr, int size)
{
	unsigned int sum = 0;
	int a;
	for (a = 0; a < size; a++) {
		sum += sumDigits(arr[a]);
	}
	return sum;
}
 
void listAllSmithNumbers(unsigned int maxSmith)
{
	unsigned int *arr;
	unsigned int a;
	for (a = 4; a < maxSmith; a++) {
		int numfactors = numPrimeFactors(a);
		arr = malloc(numfactors * sizeof(unsigned int));
		if (numfactors < 2) {
			continue;
		}
		primeFactors(a, arr);
		if (sumDigits(a) == sumFactors(arr, numfactors)) {
			printf("%4d ", a);
		}
		free(arr);
	}
}
 
