typedef struct stack {
    int top;
    unsigned capacity;
    int* array;
} stack;
 
stack* createStack(unsigned capacity) {
    stack* s = (stack*)malloc(sizeof(stack));
    s->top = -1;
    s->capacity = capacity;
    s->array = (int*)malloc(s->capacity * sizeof(int));
    return s;
}
 
int isEmpty(stack* s) {
    return s->top == -1;
}
 
int peek(stack* s) {
    return s->array[s->top];
}
 
void push(stack* s, int op) {
    s->array[++s->top] = op;
}
 
int pop(stack* s) {
    return s->array[s->top--];
}
 
void deleteStack(stack* s) {
    free(s->array);
    free(s);
}
 
char* infixToPostfix(char* infix) {
    const char* ops = "-+/*^";
    char* postfix = (char*)malloc(strlen(infix) * sizeof(char));
    stack* s = createStack(strlen(infix));
    int i = 0;
    int j = 0;
    while (infix[i]) {
        if (isspace(infix[i])) {
            i++;
            continue;
        }
        char c = infix[i];
        int idx = strchr(ops, c) - ops;
        if (idx!= -1) {
            if (isEmpty(s))
                push(s, idx);
            else {
                while (!isEmpty(s)) {
                    int prec2 = peek(s) / 2;
                    int prec1 = idx / 2;
                    if (prec2 > prec1 || (prec2 == prec1 && c!= '^'))
                        postfix[j++] = ops[pop(s)];
                    else break;
                }
                push(s, idx);
            }
        }
        else if (c == '(') {
            push(s, -2);
        }
        else if (c == ')') {
            while (peek(s)!= -2)
                postfix[j++] = ops[pop(s)];
            pop(s);
        }
        else {
            postfix[j++] = c;
        }
        i++;
    }
    while (!isEmpty(s))
        postfix[j++] = ops[pop(s)];
    postfix[j] = '\0';
    deleteStack(s);
    return postfix;
}
 
