int *caStep(int *old, int len) {
  int *state = malloc(len * sizeof(int));
  int *old_copy = malloc((len + 2) * sizeof(int));
  memcpy(old_copy + 1, old, len * sizeof(int));
  old_copy[0] = 0;
  old_copy[len + 1] = 0;

  for (int i = 1; i < len + 1; i++) {
    switch (old_copy[i - 1] + old_copy[i + 1]) {
      case 0: state[i - 1] = 0; break;
      case 1: state[i - 1] = (old_copy[i] == 1)? 1 : 0; break;
      case 2: state[i - 1] = (old_copy[i] == 1)? 0 : 1; break;
    }
  }
  free(old_copy);
  return state;
}

