int do_count(int n, int m, int **cache, int *coins) {
  if (n < 0 || m < 0)
    return 0;
  else if (cache[n][m]!= -1)
    return cache[n][m];
  else
    return cache[n][m] = do_count(n-coins[m], m, cache, coins) + do_count(n, m-1, cache, coins);
}
 
int make_change(int amount, int *coins, int n_coins) {
  int **cache;
  int i, j;
  cache = malloc(sizeof(int *) * (amount+1));
  for (i = 0; i <= amount; i++) {
    cache[i] = malloc(sizeof(int) * n_coins);
    for (j = 0; j < n_coins; j++)
      cache[i][j] = i == 0? 1 : -1;
  }
  int result = do_count(amount, n_coins - 1, cache, coins);
  for (i = 0; i <= amount; i++)
    free(cache[i]);
  free(cache);
  return result;
}
 
