typedef struct node {
	int val;
	struct node *next;
} node;

node *flatten(node *lst) {
	node *head = NULL;
	node *tail = NULL;
	node *tmp;
	while (lst!= NULL) {
		if (lst->val == 0) {
			tmp = lst->next;
			free(lst);
			lst = tmp;
		} else {
			if (head == NULL) {
				head = lst;
				tail = lst;
			} else {
				tail->next = lst;
				tail = lst;
			}
			lst = lst->next;
		}
	}
	if (tail!= NULL) {
		tail->next = NULL;
	}
	return head;
}

