int mod_exp(mpz_t b, mpz_t e, mpz_t n, mpz_t result)
{
    if (mpz_sgn(n) == 0) {
        return -1;
    }
    if (mpz_cmp(b, n) >= 0) {
        return -1;
    }
    if (mpz_cmp_ui(b, 1) == 0) {
        return -1;
    }
 
    mpz_t bb, ee;
    mpz_init_set(bb, b);
    mpz_init_set(ee, e);
    mpz_init_set_ui(result, 1);
    while (mpz_sgn(ee)!= 0) {
        if (mpz_odd_p(ee)) {
            mpz_mul(result, result, bb);
            mpz_mod(result, result, n);
        }
        mpz_fdiv_q_2exp(ee, ee, 1);
        mpz_mul(bb, bb, bb);
        mpz_mod(bb, bb, n);
    }
    mpz_clear(bb);
    mpz_clear(ee);
    return 0;
}
 
