def encode_neg_base(n, b):
    if b < -62 or b > -1:
        raise ValueError("base must be between -62 and -1 inclusive")
    if n == 0:
        return "0"
    out = []
    while n!= 0:
        rem = n % b
        n //= b
        if rem < 0:
            n += 1
            rem -= b
        out.append(digits[rem])
    return reverse("".join(out))
 
def decode_neg_base(ns, b):
    if b < -62 or b > -1:
        raise ValueError("base must be between -62 and -1 inclusive")
    if ns == "0":
        return 0
    total = 0
    bb = 1
    for c in reverse(ns):
        total += digits.index(c) * bb
        bb *= b
    return total
 
