DIGITS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'

# convert a base 10 integer into a negative base value (as a string)

def negative_base_encode(n, b):
    if (b < -62) or (b > -2):
        raise 'base out of range'
    if n == 0:
        return '0'
    revdigs = []
    while n!= 0:
        n, r = divmod(n, b)
        if r < 0:
            n += 1
            r -= b
        revdigs.append(r)
    return ''.join(reversed([DIGITS[digit] for digit in revdigs]))

# convert a negative base value (as a string) into a base 10 integer

def negative_base_decode(n, b):
    if (b < -62) or (b > -2):
        raise 'base out of range'
    value = 0
    for inx, ch in enumerate(reversed(n)):
        value += DIGITS.index(ch) * b**inx
    return value

