typedef struct {
    int gold;
    int silver;
    int bronze;
} Medals;

typedef struct {
    char *key;
    Medals value;
} Entry;

typedef struct {
    int capacity;
    int size;
    Entry *entries;
} HashMap;

HashMap *new_hash_map(int capacity) {
    HashMap *map = malloc(sizeof(HashMap));
    map->capacity = capacity;
    map->size = 0;
    map->entries = malloc(sizeof(Entry) * capacity);
    return map;
}

int hash(char *key, int capacity) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % capacity;
}

void insert(HashMap *map, char *key, Medals value) {
    int index = hash(key, map->capacity);
    while (map->entries[index].key!= NULL) {
        index = (index + 1) % map->capacity;
    }
    map->entries[index].key = key;
    map->entries[index].value = value;
    map->size++;
}

Medals *get(HashMap *map, char *key) {
    int index = hash(key, map->capacity);
    while (map->entries[index].key!= NULL) {
        if (strcmp(map->entries[index].key, key) == 0) {
            return &map->entries[index].value;
        }
        index = (index + 1) % map->capacity;
    }
    return NULL;
}

void print_medals(char *country, Medals medals) {
    printf("%s has had %d gold medals, %d silver medals, and %d bronze medals\n", country, medals.gold, medals.silver, medals.bronze);
}

