} CIDR;
 
CIDR* CIDR_new(int address, int maskLength) {
    CIDR* cidr = malloc(sizeof(CIDR));
    cidr->address = address;
    cidr->maskLength = maskLength;
    return cidr;
}
 
CIDR* CIDR_newFromString(const char* str) {
    int address = 0;
    int maskLength = 0;
    int a = 0;
    int b = 0;
    int c = 0;
    int d = 0;
    int n = sscanf(str, "%d.%d.%d.%d/%d", &a, &b, &c, &d, &maskLength);
    if (n!= 5) {
        errno = EINVAL;
        return NULL;
    }
    if (a < 0 || a > 255 || b < 0 || b > 255 || c < 0 || c > 255 || d < 0 || d > 255) {
        errno = EINVAL;
        return NULL;
    }
    address = (a << 24) | (b << 16) | (c << 8) | d;
    if (maskLength < 1 || maskLength > 32) {
        errno = EINVAL;
        return NULL;
    }
    int mask = ~((1 << (32 - maskLength)) - 1);
    address &= mask;
    return CIDR_new(address, maskLength);
}
 
char* CIDR_toString(CIDR* cidr) {
    int address = cidr->address;
    int maskLength = cidr->maskLength;
    int a = (address >> 24) & 0xFF;
    int b = (address >> 16) & 0xFF;
    int c = (address >> 8) & 0xFF;
    int d = address & 0xFF;
    char* str = malloc(18);
    sprintf(str, "%d.%d.%d.%d/%d", a, b, c, d, maskLength);
    return str;
}
 
