//  Title:  Determine if a string has all unique characters
 
typedef struct {
    char key;
    int index;
} char_index_t;
 
int main(int argc, char *argv[]) {
    char *strings[] = { "", ".", "abcABC", "XYZ ZYX", "1234567890ABCDEFGHIJKLMN0PQRSTUVWXYZ" };
    printf("%-40s  %2s  %10s  %8s  %s  %s\n", "String", "Length", "All Unique", "1st Diff", "Hex", "Positions");
    printf("%-40s  %2s  %10s  %8s  %s  %s\n", "------------------------", "------", "----------", "--------", "---", "---------");
    for ( int i = 0; i < sizeof(strings)/sizeof(strings[0]); i++ ) {
        processString(strings[i]);
    }
    return 0;
}
 
void processString(char *input) {
    char_index_t *charMap = (char_index_t *)malloc(sizeof(char_index_t) * 256);
    assert(charMap!= NULL);
    memset(charMap, 0, sizeof(char_index_t) * 256);
    char dup = 0;
    int index = 0;
    int pos1 = -1;
    int pos2 = -1;
    for ( char *key = input; *key!= '\0'; key++ ) {
        index++;
        if ( charMap[*key].key!= 0 ) {
            dup = *key;
            pos1 = charMap[*key].index;
            pos2 = index;
            break;
        }
        charMap[*key].key = *key;
        charMap[*key].index = index;
    }
    char *unique = dup == 0? "yes" : "no";
    char *diff = dup == 0? "" : "'";
    diff[1] = dup;
    diff[2] = '\'';
    diff[3] = '\0';
    char *hex = dup == 0? "" : "0x";
    char hex_str[10];
    sprintf(hex_str, "%X", dup);
    hex[2] = hex_str[0];
    hex[3] = hex_str[1];
    hex[4] = '\0';
    char *position = dup == 0? "" : "";
    char position_str[10];
    sprintf(position_str, "%d %d", pos1, pos2);
    strcpy(position, position_str);
    printf("%-40s  %-6d  %-10s  %-8s  %-3s  %-5s\n", input, strlen(input), unique, diff, hex, position);
    free(charMap);
}

#include <stdio.h>
