#define MAX_TOKENS 100
 
typedef struct {
    char *tokens[MAX_TOKENS];
    int count;
} Tokenizer;
 
void tokenizeString(Tokenizer *tokenizer, char *s, char sep, char escape) {
    char *token = NULL;
    bool inEscape = false;
    int i = 0;
 
    tokenizer->count = 0;
    token = strtok(s, &sep);
    while (token!= NULL) {
        if (inEscape) {
            inEscape = false;
        } else if (token[0] == escape) {
            inEscape = true;
            token = strtok(NULL, &sep);
            continue;
        } else {
            tokenizer->tokens[i++] = token;
            tokenizer->count++;
            token = strtok(NULL, &sep);
        }
    }
}
 
void printTokens(Tokenizer *tokenizer) {
    int i;
 
    for (i = 0; i < tokenizer->count; i++) {
        printf("%s\n", tokenizer->tokens[i]);
    }
}
 
int main(int argc, char *argv[]) {
    char *sample = "one^|uno||three^^^^|four^^^|^cuatro|";
    char separator = '|';
    char escape = '^';
    Tokenizer tokenizer;
 
    printf("%s\n", sample);
    tokenizeString(&tokenizer, sample, separator, escape);
    printTokens(&tokenizer);
 
    return 0;
}

