void superEllipse(cairo_t *cr, double n, int a) {
    double hw = 250;
    double hh = 250;
 
    // calculate y for each x
    double *y = malloc(sizeof(double) * (a + 1));
    for (int x = 0; x <= a; x++) {
        double aa = pow(a, n);
        double xx = pow(x, n);
        y[x] = pow(aa - xx, 1.0 / n);
    }
 
    // draw quadrants
    for (int x = a; x >= 0; x--) {
        cairo_line_to(cr, hw + x, hh - y[x]);
    }
    for (int x = 0; x <= a; x++) {
        cairo_line_to(cr, hw + x, hh + y[x]);
    }
    for (int x = a; x >= 0; x--) {
        cairo_line_to(cr, hw - x, hh + y[x]);
    }
    for (int x = 0; x <= a; x++) {
        cairo_line_to(cr, hw - x, hh - y[x]);
    }
 
    cairo_set_source_rgb(cr, 1, 1, 1); // white ellipse
    cairo_fill(cr);
}
 
