typedef double (*Y)(double);
typedef double (*Yd)(double, double);
 
void rungeKutta4(double t0, double tz, double dt, Y y, Yd yd) {
    double tn = t0;
    double yn = y(tn);
    int z = (tz - t0) / dt;
    for (int i = 0; i <= z; i++) {
        if (i % 10 == 0) {
            double exact = y(tn);
            double error = yn - exact;
            printf("%4.1f  %10f  %10f  %9f\n", tn, yn, exact, error);
        }
        if (i == z) break;
        double dy1 = dt * yd(tn, yn);
        double dy2 = dt * yd(tn + 0.5 * dt, yn + 0.5 * dy1);
        double dy3 = dt * yd(tn + 0.5 * dt, yn + 0.5 * dy2);
        double dy4 = dt * yd(tn + dt, yn + dy3);
        yn += (dy1 + 2.0 * dy2 + 2.0 * dy3 + dy4) / 6.0;
        tn += dt;
    }
}
 
double y(double t) {
    double x = t * t + 4.0;
    return x * x / 16.0;
}
 
double yd(double t, double yt) {
    return t * sqrt(yt);
}
 
