typedef int (*Order)(const void *a, const void *b);
 
void mergesort(void *base, size_t nmemb, size_t size, Order order)
{
  if (nmemb > 1)
  {
    size_t middle = nmemb / 2;
    mergesort(base, middle, size, order);
    mergesort((char *)base + middle * size, nmemb - middle, size, order);
    char *first = (char *)base;
    char *middle_ptr = (char *)base + middle * size;
    char *last = (char *)base + nmemb * size;
    char *buffer = malloc(nmemb * size);
    char *buffer_ptr = buffer;
    while (first < middle_ptr && middle_ptr < last)
    {
      if (order(first, middle_ptr) < 0)
      {
        memcpy(buffer_ptr, first, size);
        first += size;
      }
      else
      {
        memcpy(buffer_ptr, middle_ptr, size);
        middle_ptr += size;
      }
      buffer_ptr += size;
    }
    while (first < middle_ptr)
    {
      memcpy(buffer_ptr, first, size);
      first += size;
      buffer_ptr += size;
    }
    while (middle_ptr < last)
    {
      memcpy(buffer_ptr, middle_ptr, size);
      middle_ptr += size;
      buffer_ptr += size;
    }
    memcpy(base, buffer, nmemb * size);
    free(buffer);
  }
}
 
void mergesort_int(int *base, size_t nmemb)
{
  mergesort(base, nmemb, sizeof(int), (Order)intcmp);
}
 
