char *enc(char *bd, char *pt) {
    char *ct = malloc(strlen(pt) * 2);
    char *enc = malloc(256);
    char *row[4];
    row[0] = strtok(bd, "\n");
    for (int i = 1; i < 4; i++) {
        row[i] = strtok(NULL, "\n");
    }
    char r2d = row[2][0];
    char r3d = row[3][0];
    for (int col = 1; col <= 10; col++) {
        char d = row[0][col];
        enc[row[1][col]] = d;
        enc[row[2][col]] = r2d + d;
        enc[row[3][col]] = r3d + d;
    }
    char num = enc['/'];
    for (int i = 0; i < strlen(pt); i++) {
        char c = pt[i];
        if (c >= '0' && c <= '9') {
            ct[i] = num;
            ct[i+1] = c;
            i++;
        } else {
            if (c >= 'a' && c <= 'z') {
                c -= 'a' - 'A';
            }
            ct[i] = enc[c];
        }
    }
    return ct;
}
 
char *dec(char *bd, char *ct) {
    char *pt = malloc(strlen(ct));
    char *row[4];
    row[0] = strtok(bd, "\n");
    for (int i = 1; i < 4; i++) {
        row[i] = strtok(NULL, "\n");
    }
    int cx[10];
    for (int i = 1; i <= 10; i++) {
        cx[row[0][i] - '0'] = i;
    }
    char r2d = row[2][0];
    char r3d = row[3][0];
    for (int i = 0; i < strlen(ct); i++) {
        int r;
        char d = ct[i];
        switch (d) {
        case r2d:
            r = 2;
            break;
        case r3d:
            r = 3;
            break;
        default:
            pt[i] = row[1][cx[d]];
            continue;
        }
        i++;
        if (row[r][cx[ct[i] - '0']] == '/') {
            i++;
            pt[i] = ct[i];
        } else {
            pt[i] = row[r][cx[ct[i] - '0']];
        }
    }
    return pt;
}
 
