int binomial(int n, int k) {
    if (n < k) return 0;
    if (n == 0 || k == 0) return 1;
    int num = 1;
    for (int i = k + 1; i <= n; i++) num *= i;
    int den = 1;
    for (int i = 2; i <= n - k; i++) den *= i;
    return num / den;
}
 
