    int **m = malloc(n * sizeof(int *));
    for (int i = 0; i < n; i++) {
        m[i] = malloc(n * sizeof(int));
        for (int j = 0; j < n; j++) m[i][j] = binomial(j, i);
    }
    return m;
}
 
int **pascalLowerTriangular(int n) {
    int **m = malloc(n * sizeof(int *));
    for (int i = 0; i < n; i++) {
        m[i] = malloc(n * sizeof(int));
        for (int j = 0; j < n; j++) m[i][j] = binomial(i, j);
    }
    return m;
}
 
int **pascalSymmetric(int n) {
    int **m = malloc(n * sizeof(int *));
    for (int i = 0; i < n; i++) {
        m[i] = malloc(n * sizeof(int));
        for (int j = 0; j < n; j++) m[i][j] = binomial(i + j, i);
    }
