}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void Sort(int *old, int length)
{
    int i, j;
    int *tmp = (int *)malloc(length * sizeof(int));
    for (int shift = 31; shift > -1; --shift)
    {
        j = 0;
        for (i = 0; i < length; ++i)
        {
            bool move = (old[i] << shift) >= 0;
            if (shift == 0?!move : move)  // shift the 0's to old's head
                old[i-j] = old[i];
            else                            // move the 1's to tmp
                tmp[j++] = old[i];
        }
        memcpy(old + length - j, tmp, j * sizeof(int));
    }
    free(tmp);
}

int main()
{
    int old[] = { 2, 5, 1, -3, 4 };
    int length = sizeof(old) / sizeof(int);
    int i;
    for (i = 0; i < length; ++i)
        printf("%d ", old[i]);
    printf("\n");
    Sort(old, length);
    for (i = 0; i < length; ++i)
        printf("%d ", old[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
 
struct g_args {
	int *i;
	int i_len;
	int *c;
};
 
void *g(void *arg) {
	struct g_args *args = arg;
	int *i = malloc(args->i_len * sizeof(int));
	memcpy(i, args->i, args->i_len * sizeof(int));
	int sum = 0;
	for (int j = 0; j < args->i_len; j++) {
		args->c[j] = i[j];
		sum += i[j];
	}
	for (;;) {
		for (int j = 0; j < args->i_len; j++) {
			args->c[j + args->i_len] = sum;
			i[j] = sum;
			sum += sum - i[j];
		}
	}
}
 
int main() {
	struct g_args args[4] = {
		{
			.i = (int[]){1, 1},
			.i_len = 2,
		},
		{
			.i = (int[]){1, 1, 2},
			.i_len = 3,
		},
		{
			.i = (int[]){1, 1, 2, 4},
			.i_len = 4,
		},
		{
			.i = (int[]){2, 1},
			.i_len = 2,
		},
	};
	for (int i = 0; i < 4; i++) {
		args[i].c = malloc(20 * sizeof(int));
		pthread_t t;
		pthread_create(&t, NULL, g, &args[i]);
		for (int j = 0; j < 10; j++) {
			printf("%4d", args[i].c[j]);
		}
		printf("\n");
	}
}

double Factorial(double nValue)
   {
       double result = nValue;
       double result_next;
       double pc = nValue;
       do
       {
           result_next = result*(pc-1);
           result = result_next;
           pc--;
       }while(pc>2);
       nValue = result;
       return nValue;
   }
 
double binomialCoefficient(double n, double k)
   {
       if (abs(n - k) < 1e-7 || k  < 1e-7) return 1.0;
       if( abs(k-1.0) < 1e-7 || abs(k - (n-1)) < 1e-7)return n;
       return Factorial(n) /(Factorial(k)*Factorial((n - k)));
   }

